# Stable binary stanzas are generated by the tagged release workflow.
class GitTwig < Formula
  desc "Lightweight Git worktrees using native copy-on-write files"
  homepage "https://github.com/leostera/git-twig"
  license "MIT"
  head "https://github.com/leostera/git-twig.git", branch: "main"

  depends_on "rust" => :build
  depends_on "git"

  def install
    system "cargo", "install", "--locked", "--path", "crates/git-twig", "--root", prefix
    man1.install "crates/git-twig/man/git-twig.1"
  end

  test do
    assert_match "git-twig", shell_output("#{bin}/git-twig --version")
    system "git", "init", "-b", "main", "source"
    cd "source" do
      system "git", "config", "user.name", "Homebrew"
      system "git", "config", "user.email", "brew@example.invalid"
      (testpath/"source/file").write("hello")
      system "git", "add", "."
      system "git", "commit", "-m", "seed"
      system bin/"git-twig", "add", "--detach", "../copy"
      assert_equal "hello", (testpath/"copy/file").read
    end
  end
end
